    [Xunit.Fact]
    public static void TestAPageOfThreeInksSeparatesIntoThreeLayersBySize() {
        emon.Port.Bitmap b = emon.Port.BitmapNew(100, 80, 3);
        emon.Port.Cells ws = emon.Port.NewCells();
        NtPage3(b);
        Norm.NmWsInit(ws);
        emon.Port.BitmapHistRgb(b, ws, Norm.NmWsHist());
        emon.Testport.AssertEq(NtLayers(b, ws), 3, "paper and three inks: three layers");
        emon.Testport.AssertEq(Norm.NmLayerCount(ws), 3, "the count is kept");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 0, 0), 800, "layer 1 is the light grey block, the largest");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 1, 0), 620, "layer 2 is black and holds its anti-aliased edge: 600 + 20");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 2, 0), 400, "layer 3 is the blue block");
        emon.Testport.AssertEq(Norm.NmPaperGray(ws), 255, "the paper bin is white");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 0, 8), Evidence.IrLight(), "light grey: low chroma, lightness over ink-light");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 1, 8), Evidence.IrBody(), "black: the body");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 2, 8), Evidence.IrColor(), "blue: colour");
        emon.Testport.AssertEq(Norm.NmLayerGet(ws, 2, 4), 17, "blue's mean red is its bin centre, 1 * 17");
    }
    [Xunit.Fact]
    public static void TestLayerMasksAreOneLutPassAndHoldExactlyTheirInk() {
        emon.Port.Bitmap b = emon.Port.BitmapNew(100, 80, 3);
        emon.Port.Bitmap m = emon.Port.BitmapNew(100, 80, 1);
        emon.Port.Bitmap lab = emon.Port.BitmapNew(100, 80, 1);
        emon.Port.Cells ws = emon.Port.NewCells();
        NtPage3(b);
        Norm.NmWsInit(ws);
        emon.Port.BitmapHistRgb(b, ws, Norm.NmWsHist());
        NtLayers(b, ws);
        Norm.NmMaskInto(b, ws, 2, m);
        emon.Testport.AssertEq(NtCount(m), 620, "the body mask: 600 + the edge column");
        emon.Testport.AssertEq(emon.Port.BitmapU8(m, 10, 10, 0), 255, "inside the black block");
        emon.Testport.AssertEq(emon.Port.BitmapU8(m, 40, 10, 0), 255, "on the anti-aliased column");
        emon.Testport.AssertEq(emon.Port.BitmapU8(m, 9, 10, 0), 0, "outside");
        emon.Testport.AssertEq(emon.Port.BitmapU8(m, 60, 40, 0), 0, "the blue block is not in it");
        Norm.NmMaskInto(b, ws, 3, m);
        emon.Testport.AssertEq(NtCount(m), 400, "the blue mask");
        emon.Testport.AssertEq(emon.Port.BitmapU8(m, 79, 59, 0), 255, "its last pixel");
        Norm.NmLabelInto(b, ws, lab);
        emon.Testport.AssertEq(emon.Port.BitmapU8(lab, 0, 0, 0), 0, "paper is 0");
        emon.Testport.AssertEq(emon.Port.BitmapU8(lab, 10, 50, 0), 1, "the grey block's id");
        emon.Testport.AssertEq(emon.Port.BitmapU8(lab, 10, 10, 0), 2, "black's id");
        emon.Testport.AssertEq(emon.Port.BitmapU8(lab, 60, 40, 0), 3, "blue's id");
    }
