    internal static int NtSauvBrute(emon.Port.Bitmap g, emon.Port.Bitmap m, int r, int k, emon.Port.Cells sq) {
        // Sauvola by the definition: every window summed directly (no integral image).
        int w = emon.Port.BitmapW(g);
        int h = emon.Port.BitmapH(g);
        int x = 0;
        int y = 0;
        int i = 0;
        int j = 0;
        int x0 = 0;
        int x1 = 0;
        int y0 = 0;
        int y1 = 0;
        int n = 0;
        int s = 0;
        int q = 0;
        int v = 0;
        int mean = 0;
        int vr = 0;
        int thr = 0;
        int ink = 0;
        while (y < h) {
            x = 0;
            while (x < w) {
                x0 = x - r;
                if (x0 < 0) {
                    x0 = 0;
                }
                x1 = (x + r) + 1;
                if (x1 > w) {
                    x1 = w;
                }
                y0 = y - r;
                if (y0 < 0) {
                    y0 = 0;
                }
                y1 = (y + r) + 1;
                if (y1 > h) {
                    y1 = h;
                }
                s = 0;
                q = 0;
                j = y0;
                while (j < y1) {
                    i = x0;
                    while (i < x1) {
                        v = emon.Port.BitmapU8(g, i, j, 0);
                        s += v;
                        q += v * v;
                        i += 1;
                    }
                    j += 1;
                }
                n = (x1 - x0) * (y1 - y0);
                mean = s / n;
                vr = (q / n) - (mean * mean);
                thr = mean + ((int) (((((long) mean) * ((long) k)) * ((long) ((2 * emon.Port.CellsAt(sq, vr)) - 256))) / 65536));
                if (emon.Port.BitmapU8(g, x, y, 0) < thr) {
                    emon.Port.BitmapSetU8(m, x, y, 0, 255);
                    ink += 1;
                } else {
                    emon.Port.BitmapSetU8(m, x, y, 0, 0);
                }
                x += 1;
            }
            y += 1;
        }
        return ink;
    }
