    internal static int NtTextLines(emon.Port.Bitmap b, int cdeg, int ink) {
        // Eight lines of ten two-part words (14 rows tall, a 4 px gap in each), the lines rising to the right by `cdeg`,
        // drawn in `ink` on a 1000 x 700 page.
        int co = Evidence.EvCos(cdeg);
        int si = Evidence.EvSin(cdeg);
        int li = 0;
        int wi = 0;
        int x = 0;
        int j = 0;
        int y = 0;
        int dy = 0;
        int on = 0;
        while (li < 8) {
            wi = 0;
            while (wi < 10) {
                x = 0;
                while (x < 70) {
                    on = 1;
                    if ((x >= 32) && (x < 36)) {
                        on = 0;
                    }
                    if (on == 1) {
                        dy = (int) ((((long) ((20 + (wi * 90)) + x)) * ((long) si)) / ((long) co));
                        j = 0;
                        while (j < 14) {
                            y = ((60 + (li * 70)) - dy) + j;
                            if (y >= 0) {
                                if (y < emon.Port.BitmapH(b)) {
                                    NtRect(b, (20 + (wi * 90)) + x, y, ((20 + (wi * 90)) + x) + 1, y + 1, ink, ink, ink);
                                }
                            }
                            j += 1;
                        }
                    }
                    x += 1;
                }
                wi += 1;
            }
            li += 1;
        }
        return 0;
    }
    internal static int NtSkewOf(int cdeg) {
        emon.Port.Bitmap b = emon.Port.BitmapNew(1000, 700, 1);
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells prof = emon.Port.NewCells();
        NtTextLines(b, cdeg, 255);
        return Norm.NmDeskew(b, pts, prof);
    }
    internal static int NtNear(int got, int want, int tol) {
        int d = got - want;
        if (d < 0) {
            d = 0 - d;
        }
        if (d <= tol) {
            return 1;
        }
        return 0;
    }
